#include "../boundary-kernel.cpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
static void require(bool b,const char*label){if(!b){std::fprintf(stderr,"boundary owner scope failure %s\n",label);std::abort();}}
static SABoundaryBudget limits(){SABoundaryBudget b{};b.max_commands=5;b.max_curves=4;b.max_pairs=100;b.max_cuts=100;b.max_edges=100;b.max_leases=2;b.max_sources=1;b.max_paths=1;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=5000000;b.max_limb_operations=1000000000;b.retained_bytes=1024*1024;b.workspace_bytes=1024*1024;return b;}
int main(){auto budget=limits();std::vector<uint64_t>stateA((sa_boundary_state_bytes()+7)/8),stateB(stateA.size()),arenaA(2*1024*1024/8),arenaB(arenaA.size());
 require(sa_boundary_initialize(stateA.data(),uint32_t(stateA.size()*8),55,arenaA.data(),uint32_t(arenaA.size()*8),&budget)==0&&sa_boundary_initialize(stateB.data(),uint32_t(stateB.size()*8),55,arenaB.data(),uint32_t(arenaB.size()*8),&budget)==0,"same host label distinct actual states");
 SABoundaryPath path{};SABoundarySourceBlock source{};source.key.words[0]=1;source.command_count=5;source.affine[0]=source.affine[3]=1;SAInkPathCommand commands[5]={{SA_INK_MOVE,0,{0,0}},{SA_INK_LINE,0,{1,0}},{SA_INK_LINE,0,{1,1}},{SA_INK_LINE,0,{0,1}},{SA_INK_CLOSE,0,{}}};SABoundaryLease a{},b{},next{};
 require(sa_boundary_prepare(stateA.data(),nullptr,&path,1,&source,1,commands,5,&a)==0,"actual source A captured");for(uint32_t i=0;i<4;i++)commands[i].values[0]+=7;require(sa_boundary_prepare(stateB.data(),nullptr,&path,1,&source,1,commands,5,&b)==0,"actual different source B captured");require(a.epoch==b.epoch&&a.slot==b.slot&&a.generation==b.generation&&a.owner!=b.owner,"lease binds exact actual state not repeated label");
 SABoundarySnapshot report,sentinel;std::memset(&report,0x5a,sizeof report);sentinel=report;require(sa_boundary_snapshot(stateB.data(),a,&report)==SA_INK_INVALID&&!std::memcmp(&report,&sentinel,sizeof report),"cross-owner reads fail without output");SABoundarySourceMutation mutation{};mutation.source=source;require(sa_boundary_update(stateB.data(),&a,&mutation,1,commands,5,&next)==SA_INK_INVALID,"cross-owner bases cannot replace current body");
 double rect[4]={7,0,8,1},coverage[2];require(sa_boundary_measure_coverage(stateB.data(),b,rect,1,coverage,1)==0&&coverage[0]==1&&coverage[1]==1,"actual B source remains intact");require(sa_boundary_destroy(stateA.data())==SA_INK_INVALID,"live lease prevents state storage reuse");require(sa_boundary_release(stateA.data(),a)==0&&sa_boundary_destroy(stateA.data())==0,"actual A lease retired before reuse");
 require(sa_boundary_initialize(stateA.data(),uint32_t(stateA.size()*8),56,arenaA.data(),uint32_t(arenaA.size()*8),&budget)==0&&sa_boundary_prepare(stateA.data(),nullptr,&path,1,&source,1,commands,5,&next)==0,"new owner epoch after storage reuse");require(sa_boundary_snapshot(stateA.data(),a,&report)==SA_INK_INVALID,"retired old epoch cannot bind reused storage");require(sa_boundary_release(stateA.data(),next)==0&&sa_boundary_destroy(stateA.data())==0&&sa_boundary_release(stateB.data(),b)==0&&sa_boundary_destroy(stateB.data())==0,"all actual scoped owners drained");std::printf("BOUNDARY_EXACT_OWNER_SCOPE_OK lease_bytes=%u\n",unsigned(sizeof(SABoundaryLease)));}
